// The window has both ends. Carts younger than MIN are still live - a nudge at
// 20 minutes is just annoying. Carts older than MAX are cold, and a discount
// sent to a two-week-old cart is a discount given away for nothing.
const min = Number($env.ABANDONED_CART_MIN_AGE_HOURS || 4);
const max = Number($env.ABANDONED_CART_MAX_AGE_HOURS || 48);

const now = DateTime.now().setZone($env.GENERIC_TIMEZONE || 'UTC');
const before = now.minus({ hours: min });
const after = now.minus({ hours: max });

return [
  {
    json: {
      run_at: now.toISO(),
      // WooCommerce wants ISO 8601 in the site's timezone for after/before.
      after: after.toISO({ suppressMilliseconds: true, includeOffset: false }),
      before: before.toISO({ suppressMilliseconds: true, includeOffset: false }),
      min_age_hours: min,
      max_age_hours: max,
    },
  },
];

// WooCommerce has no "abandoned cart" resource. A cart that reached checkout and
// stopped is an order left in pending or failed - that is the thing worth
// chasing, because the customer already typed their email address.
const win = $('Cart Window').first().json;
const orders = ($input.first().json.body || []).filter((o) => o && o.id);

const out = [];
for (const o of orders) {
  const email = String(o.billing?.email || '').trim().toLowerCase();
  if (!email.includes('@')) continue;

  const created = new Date(o.date_created).getTime();
  const hours = Number(((Date.now() - created) / 3600000).toFixed(1));

  out.push({
    json: {
      order_id: o.id,
      order_number: String(o.number || o.id),
      status: o.status,
      email,
      first_name: o.billing?.first_name || null,
      currency: o.currency || $env.STORE_CURRENCY || 'GBP',
      total: Number(o.total || 0),
      hours_abandoned: hours,
      returning: Number(o.customer_id || 0) > 0,
      payment_url: o.checkout_payment_url || o.payment_url || null,
      line_items: (o.line_items || []).map((li) => ({ name: li.name, quantity: li.quantity, total: Number(li.total || 0) })),
      window_after: win.after,
      window_before: win.before,
    },
  });
}

return out;

// Between the list query and this line the customer may have gone back and
// paid. Sending "you left something behind" to somebody who has just paid is
// the most common way an abandoned-cart flow embarrasses a store, so every
// order is read again immediately before the send.
//
// Items are matched on the order id rather than on position: the HTTP node
// above can reorder or drop items, and a nudge sent to the wrong customer is
// worse than no nudge at all.
const carts = $('Find Abandoned Carts').all().map((i) => i.json);

const out = [];
for (const item of $input.all()) {
  const fresh = item.json;
  const cart = carts.find((c) => String(c.order_id) === String(fresh.id));
  if (!cart) continue;

  out.push({
    json: {
      ...cart,
      status: fresh.status,
      still_abandoned: ['pending', 'failed', 'on-hold'].includes(String(fresh.status)),
      rechecked_at: new Date().toISOString(),
    },
  });
}

return out;

// The prompt gets only what the store already knows about this order, and the
// system message forbids inventing discounts, delivery dates or stock claims.
// The model writes the sentences; it never decides the offer.
const out = [];
for (const item of $input.all()) {
  const c = item.json;

  const items = (c.line_items || [])
    .map((li) => li.quantity + ' x ' + li.name + ' (' + c.currency + ' ' + Number(li.total).toFixed(2) + ')')
    .join('; ');

  const system = [
    'You write one short cart-recovery email for ' + ($env.STORE_NAME || 'the store') + '.',
    'British English, warm, no exclamation marks, no emoji, under 90 words.',
    'Mention the actual products by name. Do not invent discounts, delivery dates,',
    'stock claims or anything not given to you. Return JSON only.',
  ].join(' ');

  const user = [
    'Customer first name: ' + (c.first_name || 'there'),
    'Items left in the cart: ' + (items || 'unknown'),
    'Cart value: ' + c.currency + ' ' + Number(c.total).toFixed(2),
    'Hours since the cart was abandoned: ' + c.hours_abandoned,
    'Returning customer: ' + (c.returning ? 'yes' : 'no'),
  ].join('\n');

  out.push({
    json: {
      ...c,
      llm_request: {
        model: $env.LLM_MODEL,
        temperature: 0.4,
        max_tokens: 400,
        messages: [
          { role: 'system', content: system },
          { role: 'user', content: user },
        ],
        response_format: {
          type: 'json_schema',
          json_schema: {
            name: 'cart_nudge',
            strict: true,
            schema: {
              type: 'object',
              additionalProperties: false,
              required: ['subject', 'body', 'tone'],
              properties: {
                subject: { type: 'string', maxLength: 70 },
                body: { type: 'string' },
                tone: { type: 'string', enum: ['warm', 'practical', 'playful'] },
              },
            },
          },
        },
      },
    },
  });
}

return out;

// Wired to BOTH outputs of the LLM call. The personalisation is a nicety, not a
// dependency: if the model is down, returns prose instead of JSON, or drops a
// required field, the customer still gets a plain, honest email. Downstream
// never has to know which of the two happened - the shape is identical.
const requests = $('Build Nudge Request').all().map((i) => i.json);
const failedCall = $input.all().some((i) => i.json && i.json.error);

function template(cart, reason) {
  return {
    ...cart,
    subject: 'Your ' + ($env.STORE_NAME || 'order') + ' basket is still here',
    body:
      'Hi ' + (cart.first_name || 'there') + ',\n\nYou left ' +
      (cart.line_items || []).map((li) => li.name).join(', ') +
      ' in your basket. It is still saved if you would like to finish up.\n\nThanks.',
    copy_source: 'template_fallback',
    copy_error: String(reason).slice(0, 300),
  };
}

if (failedCall) {
  const reason = $input.first().json?.error?.message || 'LLM call failed';
  return requests.map((cart) => ({ json: template(cart, reason) }));
}

const out = [];
const responses = $input.all().map((i) => i.json);

for (let i = 0; i < requests.length; i++) {
  const cart = requests[i];
  const response = responses[i];

  let copy = null;
  let parseError = null;
  try {
    copy = JSON.parse(response?.choices?.[0]?.message?.content);
    if (!copy?.subject || !copy?.body) throw new Error('subject or body missing from the model output');
  } catch (e) {
    parseError = e.message;
  }

  if (parseError) {
    out.push({ json: template(cart, parseError) });
    continue;
  }

  out.push({
    json: {
      ...cart,
      subject: String(copy.subject).slice(0, 120),
      body: String(copy.body).slice(0, 4000),
      tone: copy.tone || null,
      copy_source: 'llm',
      copy_error: null,
    },
  });
}

return out;

// Reached from both outputs of the send. A nudge that could not be delivered
// still gets a row, with delivered = false - that column is the answer to
// "which customers did we think we emailed and did not".
const carts = $('Nudge Copy').all().map((i) => i.json);
const results = $input.all().map((i) => i.json);
const failed = results.some((r) => r && r.error);

return carts.map((c, i) => ({
  json: {
    order_id: c.order_id,
    order_number: c.order_number,
    email: c.email,
    cart_value: c.total,
    currency: c.currency,
    hours_abandoned: c.hours_abandoned,
    copy_source: c.copy_source,
    copy_error: c.copy_error || null,
    subject: c.subject,
    delivered: !failed,
    detail: failed
      ? String(results[0]?.error?.message || results[0]?.error || 'send failed').slice(0, 400)
      : null,
    external_ref: failed ? null : results[i]?.id || results[i]?.message_id || null,
    execution_id: $execution.id,
  },
}));

// Two different low-stock questions, answered together: what is nearly gone,
// and what is gone. Both open a restock task; only the second one shouts.
const threshold = Number($env.LOW_STOCK_THRESHOLD || 5);
const products = ($input.first().json.body || []).filter((p) => p && p.id);

const out = [];
for (const p of products) {
  // A product with stock management off has no number to compare, and a
  // variable parent reports the stock of its variations, not its own.
  if (!p.manage_stock) continue;
  if (p.type === 'variable') continue;

  const qty = Number(p.stock_quantity ?? 0);
  if (qty > threshold) continue;

  out.push({
    json: {
      product_id: p.id,
      sku: p.sku || null,
      name: p.name,
      stock_quantity: qty,
      threshold,
      out_of_stock: qty <= 0,
      backorders_allowed: p.backorders !== 'no',
      price: Number(p.price || 0),
      permalink_present: Boolean(p.permalink),
      // One task per product per day: a job that runs every two hours must not
      // open twelve tickets for the same shortage.
      task_key: String(p.id) + ':' + new Date().toISOString().slice(0, 10),
    },
  });
}

return out;

// Matched on task_key, which the INSERT above returns, so the alert can never
// be built from a different product than the task it references.
const products = $('Find Low Stock').all().map((i) => i.json);

return $input.all().map((item) => {
  const task = item.json;
  const p = products.find((x) => x.task_key === task.task_key) || {};

  return {
    json: {
      ...p,
      task_id: task.id,
      slack_payload: {
        text: (p.out_of_stock ? 'OUT OF STOCK: ' : 'Low stock: ') + p.name,
        blocks: [
          {
            type: 'header',
            text: { type: 'plain_text', text: (p.out_of_stock ? 'Out of stock' : 'Low stock') + ' - ' + p.name },
          },
          {
            type: 'section',
            fields: [
              { type: 'mrkdwn', text: '*SKU*\n' + (p.sku || 'n/a') },
              { type: 'mrkdwn', text: '*On hand*\n' + p.stock_quantity },
              { type: 'mrkdwn', text: '*Threshold*\n' + p.threshold },
              { type: 'mrkdwn', text: '*Backorders*\n' + (p.backorders_allowed ? 'allowed' : 'blocked') },
            ],
          },
          {
            type: 'context',
            elements: [
              { type: 'mrkdwn', text: 'Restock task ' + task.id + ' opened by n8n execution ' + $execution.id },
            ],
          },
        ],
      },
    },
  };
});

// Every tool call in this workflow routes its error output here. The scheduled
// run does not get to fail quietly at 3am: either the work happened or this
// message exists.
const failure = $input.first().json;
const error = failure?.error || failure;

return [
  {
    json: {
      failed_node: $prevNode.name,
      message: String(error?.message || error?.description || 'no message').slice(0, 800),
      slack_payload: {
        text: 'Scheduled ecommerce job degraded: ' + $prevNode.name,
        blocks: [
          { type: 'header', text: { type: 'plain_text', text: 'Scheduled job could not complete' } },
          {
            type: 'section',
            fields: [
              { type: 'mrkdwn', text: '*Workflow*\n' + $workflow.name },
              { type: 'mrkdwn', text: '*Node*\n' + $prevNode.name },
              { type: 'mrkdwn', text: '*Execution*\n' + $execution.id },
              { type: 'mrkdwn', text: '*When*\n' + new Date().toISOString() },
            ],
          },
          {
            type: 'section',
            text: { type: 'mrkdwn', text: '*Error*\n' + String(error?.message || 'no message').slice(0, 600) },
          },
        ],
      },
    },
  },
];
